// Opening book positions, generated from the lichess chess-openings database.
// Source: https://github.com/lichess-org/chess-openings (CC0-1.0, public domain)
// Regenerate with tools/gen-book.mjs. 7855 positions from 3810 named openings.
//
// A position is "in book" if its key is here. Keys are a 48-bit FNV-1a hash of the
// first four FEN fields (placement, side to move, castling rights, en passant), so
// two positions that differ only in move counters share a key -- which is what we
// want, and castling rights keep a shuffled-king position out of the book.

const KEYS = new Set("".match(/.{12}/g));

export function positionKey(fen) {
  const s = fen.split(" ").slice(0, 4).join(" ");
  let h1 = 0x811c9dc5, h2 = 0x01000193;
  for (let i = 0; i < s.length; i++) {
    h1 = Math.imul(h1 ^ s.charCodeAt(i), 0x01000193) >>> 0;
    h2 = Math.imul(h2 ^ s.charCodeAt(i), 0x85ebca6b) >>> 0;
  }
  return h1.toString(16).padStart(8, "0") + (h2 & 0xffff).toString(16).padStart(4, "0");
}

/** Is this position a known opening position? */
export function isBookPosition(fen) {
  return KEYS.has(positionKey(fen));
}
